/* orbits7.c - orbits of the normal-form group on the seven-qubit solutions of family7.c.
 *
 * A solution is a pair (s, w): T = CS(0,1) CS(2,3) CS(4,5) + [CCZ gates w inside qubits 0..5] + [CCZ gates
 * {6,j,k} for the edges (j,k) of s].  The group G0 = { g in GL(7,2) : g e6 = e6, g preserves B = T(x,x,.) }
 * has order 64 |Sp(6,2)| = 92 897 280 and maps solutions to solutions.  It is generated by the maps
 * x -> x + phi(x) u  with (u in W, phi = B(.,u))  [symplectic transvections]  and  (u = e6, phi any
 * functional on W).  Two forms of this family are related by a change of basis exactly when their normal
 * forms are in one orbit of G0.
 *
 * input:  binary file of uint64 codes  s | (w << 15)   (the concatenated output of family7)
 * output: one line per orbit: size, stabiliser order, representative with the fewest CCZ gates.
 * Expected: 13271040 solutions, no image outside the set, one orbit, stabiliser of order 7.
 *
 * usage: orbits7 solutions.bin        (prints ORBITS7-PASS when the result is the expected one)
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define N 7
static int ej[15], ek[15], tj[20], tk[20], tl[20];
static uint64_t *codes; static size_t ncodes;
static uint32_t *parent;

static int cmp_u64(const void *a, const void *b) {
    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;
    return x < y ? -1 : x > y;
}
static uint32_t find(uint32_t x) {
    while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
    return x;
}
static void build(uint64_t code, uint8_t T[N][N]) {
    uint32_t s = (uint32_t)(code & 0x7fff), w = (uint32_t)(code >> 15);
    memset(T, 0, N * N);
    for (int i = 0; i < 3; i++) {
        int j = 2 * i, k = 2 * i + 1;
        T[j][j] ^= 1u << k; T[j][k] ^= 1u << j; T[j][k] ^= 1u << k;
        T[k][k] ^= 1u << j; T[k][j] ^= 1u << k; T[k][j] ^= 1u << j;
    }
    for (int i = 0; i < 15; i++) if ((s >> i) & 1) {
        int j = 6, k = ej[i], l = ek[i];
        T[j][k] ^= 1u << l; T[j][l] ^= 1u << k; T[k][j] ^= 1u << l; T[k][l] ^= 1u << j; T[l][j] ^= 1u << k; T[l][k] ^= 1u << j;
    }
    for (int i = 0; i < 20; i++) if ((w >> i) & 1) {
        int j = tj[i], k = tk[i], l = tl[i];
        T[j][k] ^= 1u << l; T[j][l] ^= 1u << k; T[k][j] ^= 1u << l; T[k][l] ^= 1u << j; T[l][j] ^= 1u << k; T[l][k] ^= 1u << j;
    }
}
/* T'(x,y,z) = T(gx,gy,gz), g = I + u phi^T  (u, phi as bit masks) */
static void act(uint8_t T[N][N], uint32_t u, uint32_t phi) {
    uint8_t U[N];
    for (int k = 0; k < N; k++) { U[k] = 0; for (int i = 0; i < N; i++) if ((u >> i) & 1) U[k] ^= T[i][k]; }
    for (int j = 0; j < N; j++) if ((phi >> j) & 1) for (int k = 0; k < N; k++) T[j][k] ^= U[k];
    for (int j = 0; j < N; j++) { U[j] = 0; for (int i = 0; i < N; i++) if ((u >> i) & 1) U[j] ^= T[j][i]; }
    for (int k = 0; k < N; k++) if ((phi >> k) & 1) for (int j = 0; j < N; j++) T[j][k] ^= U[j];
    for (int j = 0; j < N; j++) for (int k = 0; k < N; k++)
        if (__builtin_parity(T[j][k] & u)) T[j][k] ^= (uint8_t)phi;
}
static int extract(uint8_t T[N][N], uint64_t *code) {
    /* check the normal form: CS part and T(e6,e6,.) = 0 */
    for (int j = 0; j < N; j++) for (int k = 0; k < N; k++) {
        int want = 0;
        if (j != k && j < 6 && k < 6 && (j / 2 == k / 2)) want = 1;
        if (((T[j][j] >> k) & 1) != want) return 0;
    }
    uint32_t s = 0, w = 0;
    for (int i = 0; i < 15; i++) if ((T[6][ej[i]] >> ek[i]) & 1) s |= 1u << i;
    for (int i = 0; i < 20; i++) if ((T[tj[i]][tk[i]] >> tl[i]) & 1) w |= 1u << i;
    *code = (uint64_t)s | ((uint64_t)w << 15);
    return 1;
}

int main(int argc, char **argv) {
    if (argc < 2) return 2;
    int e = 0;
    for (int j = 0; j < 6; j++) for (int k = j + 1; k < 6; k++) { ej[e] = j; ek[e] = k; e++; }
    e = 0;
    for (int j = 0; j < 6; j++) for (int k = j + 1; k < 6; k++) for (int l = k + 1; l < 6; l++) { tj[e] = j; tk[e] = k; tl[e] = l; e++; }
    FILE *f = fopen(argv[1], "rb");
    if (!f) return 2;
    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);
    ncodes = (size_t)sz / 8;
    codes = malloc(ncodes * 8);
    if (fread(codes, 8, ncodes, f) != ncodes) return 2;
    fclose(f);
    qsort(codes, ncodes, 8, cmp_u64);
    parent = malloc(ncodes * 4);
    for (size_t i = 0; i < ncodes; i++) parent[i] = (uint32_t)i;
    /* generators */
    uint32_t gu[32], gphi[32]; int ng = 0;
    for (int j = 0; j < 6; j++) {             /* transvection along e_j: phi = B(., e_j) = e_{j^1}^* */
        gu[ng] = 1u << j; gphi[ng] = 1u << (j ^ 1); ng++;
    }
    for (int j = 0; j < 6; j++) for (int k = j + 1; k < 6; k++) {   /* transvection along e_j + e_k */
        gu[ng] = (1u << j) | (1u << k); gphi[ng] = (1u << (j ^ 1)) ^ (1u << (k ^ 1)); ng++;
    }
    for (int j = 0; j < 6; j++) { gu[ng] = 1u << 6; gphi[ng] = 1u << j; ng++; }   /* shifts along e6 */
    size_t bad = 0;
    for (size_t i = 0; i < ncodes; i++) {
        for (int g = 0; g < ng; g++) {
            uint8_t T[N][N];
            build(codes[i], T);
            act(T, gu[g], gphi[g]);
            uint64_t c2;
            if (!extract(T, &c2)) { bad++; continue; }
            uint64_t *p = bsearch(&c2, codes, ncodes, 8, cmp_u64);
            if (!p) { bad++; continue; }
            uint32_t a = find((uint32_t)i), b = find((uint32_t)(p - codes));
            if (a != b) parent[a] = b;
        }
    }
    printf("solutions %llu, images outside the solution set or the normal form: %llu\n",
           (unsigned long long)ncodes, (unsigned long long)bad);
    /* orbit statistics */
    uint32_t *size = calloc(ncodes, 4);
    uint64_t *best = malloc(ncodes * 8);
    for (size_t i = 0; i < ncodes; i++) best[i] = ~0ULL;
    for (size_t i = 0; i < ncodes; i++) {
        uint32_t r = find((uint32_t)i);
        size[r]++;
        uint64_t c = codes[i];
        if (best[r] == ~0ULL || __builtin_popcountll(c) < __builtin_popcountll(best[r])) best[r] = c;
    }
    int norb = 0;
    for (size_t i = 0; i < ncodes; i++) if (size[i]) {
        norb++;
        uint64_t c = best[i];
        printf("orbit %d: size %u stabiliser %.4f  fewest gates %d  s=0x%x w=0x%x\n", norb, size[i],
               92897280.0 / size[i], __builtin_popcountll(c), (unsigned)(c & 0x7fff), (unsigned)(c >> 15));
    }
    printf("orbits %d\n", norb);
    int ok = ncodes == 13271040 && bad == 0 && norb == 1;
    printf(ok ? "ORBITS7-PASS\n" : "ORBITS7-FAIL\n");
    return ok ? 0 : 1;
}
